package com.example.editor.remote.auth;

import java.time.Instant;
import java.util.List;
import com.example.editor.remote.storage.RemoteStorageProviderType;

/** Estado de autorización efímero, acotado y no persistente. deviceCode/verifier nunca salen del backend. */
record PendingRemoteAuthFlow(String state,String profileId,String connectionId,RemoteStorageProviderType provider,String verifier,String redirectUri,
        List<String> scopes,boolean deviceFlow,String deviceCode,int pollIntervalSeconds,Instant nextPollAt,Instant expiresAt,String language) {
    /** Descripción: Ejecuta la operación «authorizationCode» correspondiente a la responsabilidad de PendingRemoteAuthFlow. Entradas: state: dato de entrada necesario para la operación; profileId: identificador que delimita el recurso objetivo; connectionId: identificador que delimita el recurso objetivo; provider: dato de entrada necesario para la operación; verifier: dato de entrada necesario para la operación; redirectUri: dato de entrada necesario para la operación; scopes: dato de entrada necesario para la operación; expiresAt: dato de entrada necesario para la operación; language: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ static PendingRemoteAuthFlow authorizationCode(String state,String profileId,String connectionId,RemoteStorageProviderType provider,String verifier,
            String redirectUri,List<String> scopes,Instant expiresAt,String language){return new PendingRemoteAuthFlow(state,profileId,connectionId,provider,verifier,redirectUri,scopes,false,"",0,Instant.EPOCH,expiresAt,normalizeLanguage(language));}
    /** Descripción: Ejecuta la operación «device» correspondiente a la responsabilidad de PendingRemoteAuthFlow. Entradas: state: dato de entrada necesario para la operación; profileId: identificador que delimita el recurso objetivo; connectionId: identificador que delimita el recurso objetivo; provider: dato de entrada necesario para la operación; scopes: dato de entrada necesario para la operación; deviceCode: dato de entrada necesario para la operación; intervalSeconds: dato de entrada necesario para la operación; expiresAt: dato de entrada necesario para la operación; language: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ static PendingRemoteAuthFlow device(String state,String profileId,String connectionId,RemoteStorageProviderType provider,List<String> scopes,
            String deviceCode,int intervalSeconds,Instant expiresAt,String language){int interval=Math.max(1,intervalSeconds);return new PendingRemoteAuthFlow(state,profileId,connectionId,provider,"","",scopes,true,deviceCode,interval,Instant.now().plusSeconds(interval),expiresAt,normalizeLanguage(language));}
    /** Descripción: Ejecuta la operación «withNextPoll» correspondiente a la responsabilidad de PendingRemoteAuthFlow. Entradas: intervalSeconds: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ PendingRemoteAuthFlow withNextPoll(int intervalSeconds){int interval=Math.max(1,intervalSeconds);return new PendingRemoteAuthFlow(state,profileId,connectionId,provider,verifier,redirectUri,scopes,deviceFlow,deviceCode,interval,Instant.now().plusSeconds(interval),expiresAt,language);}
    /** Descripción: Ejecuta la operación «normalizeLanguage» correspondiente a la responsabilidad de PendingRemoteAuthFlow. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String normalizeLanguage(String value){return value!=null&&value.toLowerCase(java.util.Locale.ROOT).startsWith("es")?"es":"en";}
}
